alter table public.online_orders add column if not exists tracking_token text; alter table public.online_orders add column if not exists tracking_url text; create unique index if not exists online_orders_tracking_token_key on public.online_orders(tracking_token) where tracking_token is not null; update public.online_orders set tracking_token = encode(gen_random_bytes(24),'hex') where tracking_token is null; update public.online_orders set tracking_url = '/track/' || tracking_token where tracking_token is not null and tracking_url is null; create or replace function public.get_order_tracking(p_token text) returns jsonb language plpgsql security definer set search_path=public as $$ declare o public.online_orders%rowtype; items jsonb; begin select * into o from public.online_orders where tracking_token=p_token limit 1; if o.id is null then return jsonb_build_object('found',false); end if; select coalesce(jsonb_agg(jsonb_build_object('product_name',i.product_name,'quantity',i.quantity,'unit_price',i.unit_price,'line_total',i.line_total) order by i.id),'[]'::jsonb) into items from public.online_order_items i where i.order_id=o.id; return jsonb_build_object('found',true,'order',jsonb_build_object('order_number',o.order_number,'status',o.status,'subtotal',o.subtotal,'shipping_fee',o.shipping_fee,'total',o.total,'created_at',o.created_at,'updated_at',o.updated_at,'customer_name',o.customer_name,'shipping_address',o.shipping_address,'customer_note',o.customer_note),'items',items); end; $$; revoke all on function public.get_order_tracking(text) from public; grant execute on function public.get_order_tracking(text) to anon, authenticated;
